//   resumed  -> status segment_cleaning: hand back to wait dock (rest) (out0)
//   dropped  -> progress reset to 0, or charged & battery >= 95 for ~10 min, or
//               150-min cap: robot will NOT resume. Go to the mop gate via d_55
//               WITHOUT f_ev_restdone (unfinished rooms stay unmarked) + notify.
//   waiting  -> loop back to d_rcpoll (out3)
// out0 -> [w_54, f_ev_rest], out1 -> d_55, out2 -> notify, out3 -> d_rcpoll
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return [null,null,null,null]; }
const _ha = global.get('homeassistant') || {};
const _st = (Object.values(_ha).find(v => v && v.states) || {}).states || {};
const st = id => (_st[id] && _st[id].state);
const status = st('sensor.mr_slave_status_2');
const batt = Number(st('sensor.mr_slave_battery_2'));
const prog = Number(st('sensor.mr_slave_cleaning_progress_2'));

// Resumed on its own (Roborock recharge & resume): the dock wait takes over again.
if (status === 'segment_cleaning') {
    node.status({fill:'green', text:'resumed'});
    return [msg, null, null, null];
}

const n = (msg.rr_rc_polls || 0) + 1;
msg.rr_rc_polls = n;
const chargedFull = !isNaN(batt) && batt >= 95 && ['charging','charged','docked'].includes(status);
msg.rr_rc_full = (msg.rr_rc_full || 0) + (chargedFull ? 1 : 0);

const dropped = (!isNaN(prog) && prog === 0) || msg.rr_rc_full >= 5 || n >= 75;
if (dropped) {
    const why = n >= 75 ? 'did not resume within 150 min'
        : (prog === 0 ? 'cleared its resume flag (progress reset to 0) after recharging'
        : 'finished charging but did not resume');
    node.status({fill:'yellow', text:'no resume: ' + why});
    const notify = {notify: {title: 'Vacuum: did not resume after recharge',
        message: 'The robot recharged mid-sweep but ' + why + '. Skipping the rest of the sweep and moving on; the unfinished rooms are left unmarked.',
        tag: 'rr_no_resume', urgent: true}};
    return [null, msg, notify, null];
}
node.status({fill:'blue', text:`waiting resume: ${batt}% batt, ${prog}% done (poll ${n})`});
return [null, null, null, msg];

// Central mop-failure notice: one alert (tag rr_mop_failed, urgent) whenever the
// weekly mop pass does not complete. Deliberately does NOT stamp
// input_datetime.rr_last_mop_run, so rrMopDue's Thursday/Friday catch-up re-runs
// the mop (never Mon/Tue, never within 48 h of a mop). Clears rr_mop_pending so the stall/stop
// alerts don't also mention the mop. out0 -> notify, out1 -> restore vacuum + done.
// Once the water watch has failed this pass, later timeouts of the same pass are dropped.
if (flow.get('rr_mop_water') && !msg.rr_mop_water) { node.status({fill:'grey',shape:'ring',text:'duplicate mop failure dropped'}); return [null, null]; }
flow.set('rr_mop_pending', false);
flow.set('rr_mop_inpass', 0);
const reason = msg.rr_mop_reason || 'it did not finish';
const notify = {notify: {title: 'Vacuum: weekly mop did not finish',
    message: 'The weekly mop pass did not complete: ' + reason + '. A catch-up mop runs at the next Thursday or Friday clean this week (otherwise next Wednesday).',
    tag: 'rr_mop_failed', urgent: true}};
node.status({fill:'red', text:'mop failed'});
return [notify, msg];

// binary_sensor.mr_slave_water_shortage_2 turned on. Only matters while a mop
// pass is in progress (rr_mop_inpass = pass start ms, set by f_ev_mop). Sends
// the one urgent rr_mop_failed via f_mopfail and marks the pass incomplete
// (rr_last_mop_run is not stamped), so the next eligible day re-runs it.
// rr_mop_water makes f_mopchk / f_mopfail drop the rest of this pass's loop.
const t0 = flow.get('rr_mop_inpass') || 0;
const run = flow.get('rr_run', 'file') || {};
if (!t0 || !run.active || flow.get('rr_cancel') || flow.get('rr_mop_water')) {
    node.status({fill:'grey', shape:'ring', text:'water shortage outside a mop pass'});
    return null;
}
flow.set('rr_mop_water', true);
flow.set('rr_mop_inpass', 0);
const mins = Math.max(0, Math.round((Date.now() - t0) / 60000));
msg.rr_mop_water = true;
msg.rr_mop_reason = 'the clean-water tank ran out ' + mins + ' min into the mop pass, so it is marked incomplete. Refill the tank';
node.status({fill:'red', text:'water ran out ' + mins + ' min into the mop'});
return msg;

// Arm 'w_42': bump the wait generation + mark it pending, and stamp the
// msg so this wait's own success/timeout can be told apart from a stale firing
// left armed after an HA-reconnect recovery (f_hareconn).
const g = (flow.get('rr_waitgen') || 0) + 1;
flow.set('rr_waitgen', g);
flow.set('rr_pending', 'w_42');
msg.rr_wgen = g;
return msg;

// Arm 'w_48': bump the wait generation + mark it pending, and stamp the
// msg so this wait's own success/timeout can be told apart from a stale firing
// left armed after an HA-reconnect recovery (f_hareconn).
const g = (flow.get('rr_waitgen') || 0) + 1;
flow.set('rr_waitgen', g);
flow.set('rr_pending', 'w_48');
msg.rr_wgen = g;
return msg;

// Arm 'w_54': bump the wait generation + mark it pending, and stamp the
// msg so this wait's own success/timeout can be told apart from a stale firing
// left armed after an HA-reconnect recovery (f_hareconn).
const g = (flow.get('rr_waitgen') || 0) + 1;
flow.set('rr_waitgen', g);
flow.set('rr_pending', 'w_54');
msg.rr_wgen = g;
if (!msg.rr_sweep_t0) msg.rr_sweep_t0 = Date.now();   // f_rc minimum-sweep check
return msg;

// Arm 'w_62': bump the wait generation + mark it pending, and stamp the
// msg so this wait's own success/timeout can be told apart from a stale firing
// left armed after an HA-reconnect recovery (f_hareconn).
const g = (flow.get('rr_waitgen') || 0) + 1;
flow.set('rr_waitgen', g);
flow.set('rr_pending', 'w_62');
msg.rr_wgen = g;
return msg;

if (msg.rr_wgen !== flow.get('rr_waitgen')) { node.status({fill:'grey',shape:'ring',text:'stale wait ignored'}); return null; }
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return null; }
flow.set('rr_pending', '');
return msg;

// Arm 'wait dock (office)': bump the wait generation + mark it pending, and
// stamp the msg so this wait's own success/timeout can be told apart from a
// stale firing left armed after an HA-reconnect recovery (f_hareconn out4).
const g = (flow.get('rr_waitgen') || 0) + 1;
flow.set('rr_waitgen', g);
flow.set('rr_pending', '207dee7e272ef8ca');
msg.rr_wgen = g;
msg.rr_office_t0 = Date.now();   // office done? short-job check
return msg;

if (msg.rr_wgen !== flow.get('rr_waitgen')) { node.status({fill:'grey',shape:'ring',text:'stale wait ignored'}); return null; }
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return null; }
flow.set('rr_pending', '');
// Rachel's office (segment 9) runs as its own job after the 11-room sweep
// (2026-11-05: in one 12-segment call the robot started there, hit
// nogo_zone_detected and the whole sweep died). Back at the dock = done:
// stamp the office (out0 -> settle final + evt officedone). Home in under
// 2 min = it never really cleaned: no stamp, tell the owner, run moves on.
// No t0 (HA-reconnect recovery msg) = treated as done.
// out0 -> [d_55, evt: officedone], out1 -> [d_55], out2 -> notify
const t0 = msg.rr_office_t0;
const mins = t0 ? (Date.now() - t0) / 60000 : NaN;
if (!isNaN(mins) && mins < 2) {
    node.status({fill:'yellow', text:'office ended early: ' + mins.toFixed(1) + ' min'});
    return [null, msg, {notify: {title: "Vacuum: Rachel's office ended early",
        message: "Rachel's office was back at the dock after " + mins.toFixed(1) +
                 ' min. The run continues; the office is not marked cleaned.',
        tag: 'rr_short_zone', urgent: false}}];
}
node.status({fill:'green', text: isNaN(mins) ? 'office done (recovered)' : 'office done: ' + mins.toFixed(1) + ' min'});
return [msg, null, null];

if (msg.rr_wgen !== flow.get('rr_waitgen')) { node.status({fill:'grey',shape:'ring',text:'stale wait ignored'}); return null; }
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return null; }
// Heading home or idle beside the dock after a return: the stage dock watcher
// (f_dw, group 9) takes the stage over (one re-dock, alert, 30-min hold).
const _dw = flow.get('rr_dw');
if (_dw && _dw.state === 'watch' && _dw.wid === flow.get('rr_pending') && _dw.gen === msg.rr_wgen && _dw.retAt) {
    _dw.force = true; flow.set('rr_dw', _dw);
    node.status({fill:'yellow', text:'near the dock: dock watcher takes over'});
    return null;
}
flow.set('rr_pending', '');
msg.rr_stage = "Rachel's office (last)"; msg.rr_mins = 40; return msg;

// Arm 'wait battery ≥30% (office)': bump the wait generation + mark it pending,
// so the wait's own success/timeout can be told apart from a stale firing.
const g = (flow.get('rr_waitgen') || 0) + 1;
flow.set('rr_waitgen', g);
flow.set('rr_pending', '48ec4456670321ea');
msg.rr_wgen = g;
return msg;

if (msg.rr_wgen !== flow.get('rr_waitgen')) { node.status({fill:'grey',shape:'ring',text:'stale wait ignored'}); return null; }
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return null; }
flow.set('rr_pending', '');
return msg;

if (msg.rr_wgen !== flow.get('rr_waitgen')) { node.status({fill:'grey',shape:'ring',text:'stale wait ignored'}); return null; }
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return null; }
flow.set('rr_pending', '');
// The sweep can dock near 14%; app_segment_clean is refused on a flat battery
// and cat_mid would cancel the run. Not reaching 30% in 90 min skips the office
// only: no stamp, a notice, phase text, and on to d_55 so the mop gate still runs.
// out0 -> d_55, out1 -> tracker (officeskip), out2 -> notify
node.status({fill:'yellow', text:'office skipped: battery'});
return [msg, {rr_evt: 'officeskip'}, {notify: {title: "Vacuum: Rachel's office skipped",
    message: "The battery did not reach 30% within 90 min after the sweep, so Rachel's office was skipped. " +
             'The run continues; the office is not marked cleaned.',
    tag: 'rr_office_skipped', urgent: false}}];

const _ha = global.get('homeassistant') || {};
const _st = (Object.values(_ha).find(v => v && v.states) || {}).states || {};
const st = id => (_st[id] && _st[id].state);

flow.set('rr_zone_t', Date.now());
const m = st('select.mr_slave_cleaning_mode');
if (m === 'vacuum' || m === undefined) { node.status({fill:'green',text:String(m)}); return [msg, null]; }
node.warn('cleaning mode is ' + m + ' after set; retrying once (O)');
node.status({fill:'yellow',text:'retry: was ' + m});
return [null, msg];
